        {{ printf "" .Permalink .MediaType | safeHTML }}
	{{ end }}
	{{ range .Site.RegularPages }}


		{{ .Title }}
		{{ .Permalink }}
		{{ dateFormat "Mon, 02 Jan 2006 15:04:05" .Date.Local | safeHTML }}
		{{ with .Site.Author.email }}{{.}}{{ with $.Site.Author.name }} ({{.}}){{end}}{{end}}
		{{ .Permalink }}
		{{- .Content | html -}}

	{{ end }}
